"""Demo: flattening trees to words and reassociating through the normal form."""
from __future__ import annotations
from typing import Tuple, Union
from dataclasses import dataclass

Word = Tuple[str, ...]

@dataclass(frozen=True)
class Nil: pass
@dataclass(frozen=True)
class Leaf:
    label: str
@dataclass(frozen=True)
class Node:
    left: "PTree"
    right: "PTree"
PTree = Union[Nil, Leaf, Node]

def flatten(t: PTree) -> Word:
    if isinstance(t, Nil):  return ()
    if isinstance(t, Leaf): return (t.label,)
    return flatten(t.left) + flatten(t.right)

def rn(w: Word) -> PTree:
    if not w: return Nil()
    return Node(Leaf(w[0]), rn(w[1:]))

def show(t: PTree) -> str:
    if isinstance(t, Nil):  return "1"
    if isinstance(t, Leaf): return t.label
    return f"({show(t.left)}.{show(t.right)})"

# Two very different bracketings of the same word are canonically identified,
# and both flow through the SAME right-nested normal form.
a,b,c,d,e = (Leaf(x) for x in "abcde")
s = Node(Node(Node(Node(a,b),c),d),e)   # (((ab)c)d)e
t = Node(a, Node(b, Node(c, Node(d,e)))) # a(b(c(de)))
print("s =", show(s), "-> word", flatten(s))
print("t =", show(t), "-> word", flatten(t))
print("same word (unique reassociation exists)?", flatten(s) == flatten(t))
print("common normal form Rn(word) =", show(rn(flatten(s))))

"""Demo: counting bracketings (Catalan numbers) and checking full connectivity."""
from __future__ import annotations
from math import comb
from typing import List, Tuple, Union
from dataclasses import dataclass

@dataclass(frozen=True)
class Leaf:
    label: str
@dataclass(frozen=True)
class Node:
    left: "PTree"
    right: "PTree"
PTree = Union[Leaf, Node]
Word = Tuple[str, ...]

def flatten(t: PTree) -> Word:
    if isinstance(t, Leaf): return (t.label,)
    return flatten(t.left) + flatten(t.right)

def all_bracketings(word: Word) -> List[PTree]:
    if len(word) == 1: return [Leaf(word[0])]
    out: List[PTree] = []
    for k in range(1, len(word)):
        for L in all_bracketings(word[:k]):
            for R in all_bracketings(word[k:]):
                out.append(Node(L, R))
    return out

def catalan(n: int) -> int:
    return comb(2*n, n) // (n+1)

for n in range(1, 7):
    word = tuple("abcdefg"[:n])
    trees = all_bracketings(word)
    connected = all(flatten(s) == flatten(t) for s in trees for t in trees)
    print(f"{n} factors: {len(trees):3d} bracketings "
          f"(Catalan C_{n-1} = {catalan(n-1):3d}); fully connected = {connected}")

