from __future__ import annotations
from typing import Optional, Tuple, Union
from dataclasses import dataclass

Word = Tuple[str, ...]

@dataclass(frozen=True)
class Nil: pass
@dataclass(frozen=True)
class Leaf:
    label: str
@dataclass(frozen=True)
class Node:
    left: "PTree"
    right: "PTree"
PTree = Union[Nil, Leaf, Node]

@dataclass(frozen=True)
class Mor:
    src: PTree
    dst: PTree

def flatten(t: PTree) -> Word:
    if isinstance(t, Nil):  return ()
    if isinstance(t, Leaf): return (t.label,)
    return flatten(t.left) + flatten(t.right)

def reassociate(s: PTree, t: PTree) -> Optional[Mor]:
    """Return the UNIQUE reassociation s -> t if the leaf-words match, else None.

    Correctness rests on coherence: any two reassociations of s into t are equal,
    so returning the pair (s, t) fully specifies the morphism. Runs in O(n)."""
    if flatten(s) == flatten(t):
        return Mor(s, t)
    return None

