"""Visualization: draw a bracketing as a binary tree and its flattened word."""
import matplotlib.pyplot as plt
from typing import Tuple, Union
from dataclasses import dataclass

@dataclass(frozen=True)
class Leaf:
    label: str
@dataclass(frozen=True)
class Node:
    left: "PTree"
    right: "PTree"
PTree = Union[Leaf, Node]

def layout(t: PTree, x: float, y: float, dx: float, pts, edges):
    if isinstance(t, Leaf):
        pts.append((x, y, t.label)); return x
    lx = layout(t.left,  x - dx, y - 1, dx/1.7, pts, edges)
    rx = layout(t.right, x + dx, y - 1, dx/1.7, pts, edges)
    cx = (lx + rx) / 2
    pts.append((cx, y, "")); edges += [((cx,y),(lx,y-1)), ((cx,y),(rx,y-1))]
    return cx

def flatten(t: PTree):
    if isinstance(t, Leaf): return (t.label,)
    return flatten(t.left) + flatten(t.right)

a,b,c,d = (Leaf(x) for x in "abcd")
tree = Node(Node(a, b), Node(c, d))   # (ab)(cd)
pts, edges = [], []
layout(tree, 0, 0, 2.0, pts, edges)
plt.figure(figsize=(6, 5))
for (x1,y1),(x2,y2) in edges:
    plt.plot([x1,x2],[y1,y2], "-", color="#34495e")
for x,y,lab in pts:
    if lab:
        plt.scatter([x],[y], s=400, color="#f1c40f", zorder=3)
        plt.text(x, y, lab, ha="center", va="center", fontsize=12)
    else:
        plt.scatter([x],[y], s=120, color="#34495e", zorder=3)
plt.title("Bracketing (ab)(cd)  ->  word " + "".join(flatten(tree)))
plt.axis("off"); plt.tight_layout()
plt.savefig("bracketing_tree.png", dpi=150)
print("saved bracketing_tree.png")

