import matplotlib.pyplot as plt
import numpy as np
from typing import List, Tuple, Union
from dataclasses import dataclass

@dataclass(frozen=True)
class Leaf:
    label: str
@dataclass(frozen=True)
class Node:
    left: "PTree"
    right: "PTree"
PTree = Union[Leaf, Node]

def all_bracketings(word):
    if len(word) == 1: return [Leaf(word[0])]
    out = []
    for k in range(1, len(word)):
        for L in all_bracketings(word[:k]):
            for R in all_bracketings(word[k:]):
                out.append(Node(L, R))
    return out

def show(t: PTree) -> str:
    if isinstance(t, Leaf): return t.label
    return f"({show(t.left)}.{show(t.right)})"

def single_rotations(t):
    """Neighbours under one associator move (a rotation at some node)."""
    res = []
    if isinstance(t, Node):
        # rotate at root: (X.Y).Z <-> X.(Y.Z)
        if isinstance(t.left, Node):
            res.append(Node(t.left.left, Node(t.left.right, t.right)))
        if isinstance(t.right, Node):
            res.append(Node(Node(t.left, t.right.left), t.right.right))
        for nl in single_rotations(t.left):
            res.append(Node(nl, t.right))
        for nr in single_rotations(t.right):
            res.append(Node(t.left, nr))
    return res

